import asyncio
import signal
import weakref
from typing import Any, Awaitable, Callable, Dict, List, Sequence

__all__ = ["run_tasks"]

# One SIGINT handler per event loop, fanned out to every in-flight run_tasks
# call so that concurrent calls all shut down gracefully on the same Ctrl-C.
_sigint_entries: "weakref.WeakKeyDictionary[Any, Dict[str, Any]]" = (
    weakref.WeakKeyDictionary()
)
_SIGNAL_ERRORS = (NotImplementedError, RuntimeError, ValueError, OSError, AttributeError)


def _remove_entry(loop: Any, entry: Dict[str, Any]) -> None:
    if _sigint_entries.get(loop) is entry:
        del _sigint_entries[loop]
    if entry.get("removed"):
        return
    entry["removed"] = True
    try:
        loop.remove_signal_handler(signal.SIGINT)
    except _SIGNAL_ERRORS:
        pass
    previous = entry.get("previous")
    if previous is not None:
        try:
            signal.signal(signal.SIGINT, previous)
        except (ValueError, OSError, TypeError):
            pass


def _install_sigint_hook(loop: Any, hook: Callable[[], None]) -> Callable[[], None]:
    """Register ``hook`` for SIGINT on ``loop``; return an uninstall callable.

    Falls back to a no-op when signal handlers are unavailable (non-main
    thread, platforms without SIGINT support, ...).
    """
    entry = _sigint_entries.get(loop)
    if entry is None:
        hooks: List[Callable[[], None]] = []
        entry = {"hooks": hooks, "count": 0, "previous": None, "removed": False}

        def dispatch() -> None:
            entry["count"] += 1
            for registered in list(entry["hooks"]):
                try:
                    registered()
                except Exception:  # pragma: no cover - never break signal dispatch
                    pass
            if entry["count"] >= 3:
                # Impatient user: give SIGINT back so the next one aborts hard.
                _remove_entry(loop, entry)

        try:
            entry["previous"] = signal.getsignal(signal.SIGINT)
            loop.add_signal_handler(signal.SIGINT, dispatch)
        except _SIGNAL_ERRORS:
            return lambda: None
        _sigint_entries[loop] = entry

    entry["hooks"].append(hook)

    def uninstall() -> None:
        try:
            entry["hooks"].remove(hook)
        except ValueError:
            pass
        if not entry["hooks"]:
            _remove_entry(loop, entry)

    return uninstall

